#include <iostream>

int main()
{
    int n{};
    std::cin >> n;
    int total{ 0 };
    for (int i{ 1 }; i <= 10; ++i)
    {
        std::cout << n << " x " << i << " = " << n * i << '\n';
        total += n * i;
    }
    std::cout << "Total: " << total << '\n';
    return 0;
}
